package com.adesa.attendance.vendor;
import java.util.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class VendorRulesTest {
 @Test void requiredConditionsBankingAndConsentsAreEnforced(){var data=VendorDemoFixtures.sample(0,"ENERGY");assertThat(VendorRules.validate(data)).containsEntry("declarationAccepted",true).containsEntry("signatureConsent",true);data.put("signatureConsent",false);assertThatThrownBy(()->VendorRules.validate(data)).hasMessageContaining("Explicitly");data.put("signatureConsent",true);data.put("accountName","");assertThatThrownBy(()->VendorRules.validate(data)).hasMessageContaining("accountName");data.put("bankName","");data.put("accountNumber","");assertThat(VendorRules.validate(data)).isNotEmpty();data.put("conflict","Yes");data.put("conflictDetails","");assertThatThrownBy(()->VendorRules.validate(data)).hasMessageContaining("conflictDetails");}
 @Test void bankingFormatsAndOtherOptionsAreValidated(){var data=VendorDemoFixtures.sample(0,"ENERGY");data.put("accountNumber","123456789");assertThatThrownBy(()->VendorRules.validate(data)).hasMessageContaining("10 digits");data.put("bankFormat","ALTERNATIVE");data.put("accountNumber","GB82 WEST 1234 5698 7654 32");data.put("bankFormatDetails","Fictional IBAN example; independently verify");assertThat(VendorRules.validate(data)).containsEntry("bankFormat","ALTERNATIVE");data.put("categories",List.of("Other"));assertThatThrownBy(()->VendorRules.validate(data)).hasMessageContaining("categoryOther");}
 @Test void exactSignedWordingsAreServerControlledAndVersioned(){var data=VendorDemoFixtures.sample(1,"MEDIA");data.put("declarationWording","replaced by browser");data.put("signatureConsentWording","not accepted");var signed=VendorRules.validate(data);assertThat(signed.get("declarationWording")).isEqualTo(VendorRules.DECLARATION);assertThat(signed.get("signatureConsentWording")).isEqualTo(VendorRules.CONSENT);assertThat(signed.get("privacyWording")).isEqualTo(VendorRules.PRIVACY);data.put("formVersion","old");assertThatThrownBy(()->VendorRules.validate(data)).hasMessageContaining("form has changed");}
 @Test void authenticatedEncryptionSeparatesRecordsAndDetectsTampering(){var crypto=new VendorCrypto(Base64.getEncoder().encodeToString(new byte[32]));byte[] plain="fictional private banking information".getBytes(StandardCharsets.UTF_8);byte[] a=crypto.seal(plain,"revision:1"),b=crypto.seal(plain,"revision:1");assertThat(a).isNotEqualTo(b);assertThat(new String(a,StandardCharsets.UTF_8)).doesNotContain("banking");assertThat(crypto.open(a,"revision:1")).isEqualTo(plain);assertThatThrownBy(()->crypto.open(a,"revision:2")).isInstanceOf(IllegalStateException.class);a[a.length-1]^=1;assertThatThrownBy(()->crypto.open(a,"revision:1")).isInstanceOf(IllegalStateException.class);assertThat(crypto.fingerprint("email:a@example.test")).hasSize(64);}
 @Test void electronicSignatureStylesProduceDistinctLegibleImages(){var images=new ArrayList<byte[]>();for(String style:List.of("CLASSIC","FLOW","BOLD")){byte[] image=VendorFiles.signature("Fictional Authorised Signatory",style);assertThat(image).hasSizeGreaterThan(1000);assertThat(VendorFiles.validate(image,"signature.png",true).mime()).isEqualTo("image/png");images.add(image);}assertThat(images.get(0)).isNotEqualTo(images.get(1)).isNotEqualTo(images.get(2));}
 @Test void disguisedOrOversizedFilesAreRejected(){assertThatThrownBy(()->VendorFiles.validate("<script>malware</script>".getBytes(),"company.pdf",false)).hasMessageContaining("valid");assertThatThrownBy(()->VendorFiles.validate(new byte[2*1024*1024+1],"signature.png",true)).hasMessageContaining("allowed size");byte[] png=VendorFiles.signature("Demo","CLASSIC");assertThatThrownBy(()->VendorFiles.validate(png,"signature.jpg",true)).hasMessageContaining("filename");}
}
